    gusher: SK("Gusher", "ultimate", ["extraction", "diffusion"], 16, { merge: true, pairOnly: true, delivery: "field", range: 0, area: { shape: "radius", radius: 3 }, potency: 8, channel: "citrinitas", targetRule: "Self: every opponent within 3 tiles.", prerequisites: ["Extraction AND Diffusion equipped", "at least one barrel"], timing: "announced",
      announce: "There is oil under everything.", potencyDefinition: "8 + 6 per barrel to every opponent within 3. Every barrel is burned. Every open tile within 3 runs slick for 2 of his turns.", expiry: "Instant; the slick lasts 2 of his turns.", dependencies: ["barrels in reserve"],
      mechanism: "Merge: one strike turns the ground beneath him into a surge, and the surge into a spill.", newEffect: "hit opponents in radius 3 for 8 + 6 x barrels; barrels = 0; slick radius 3 (class-runtime oilGusher).",
      reveal: "Gusher spends every barrel he has, and leaves him standing in the middle of his own slick.", price: "His ultimate, every barrel (so no buyouts after), and a ruined field for his side too.", counter: "Leave the 3 tiles during the announcement; make him spend barrels on buyouts first.", teaches: "Extraction at scale is indistinguishable from destruction." }),
