    // hospitality + antifragility (Muse, 2026-10-14): staged, not playable
    welcome: SK("Welcome", "basic", ["hospitality"], 4, { pairOnly: true, pairs: [["mise_en_place", "hospitality"], ["hospitality", "mise_en_place"]], delivery: "field", range: 3, area: { shape: "single" }, potency: 0, channel: null,
      targetRule: "One foe within 3 that you can see (never a boss, wild creature, bystander, civilian, mediator (safe conduct), persuaded unit, unit already in a truce or in a room, unit that has not arrived, has escaped or is defeated, or unit with banked Antifragility).", prerequisites: ["a foe within 3", "no banked Antifragility on the guest", "no live room", "one Welcome per 3 rounds"],
      potencyDefinition: "Seat the guest at your table: a sealed 3x3 dining room (a table and two chairs) opens for ONE full round and the outside battle holds its breath. The guest first chooses: ACCEPT THE MEAL or REJECT HOSPITALITY (its only two actions until it chooses). Accept: nobody inside can harm anybody (no hostile act, status effect or forced movement between you, the guest and your summons); you and the guest each heal 15% of your maximum LF, recover 6 ΦF and learn two things about each other (two free studies each); a guest is fed once per battle (one that has already accepted cannot be seated again), and the shared meal warms it towards you (valence +3 toward you, +2 toward your allies; you and your allies +1 toward it) for the battle: a reasonable foe who is warm enough will rather stand down than hurt you. Reject: you, your summons and the guest may attack each other, and you are penalised: Hospitality rejected (for two rounds your stations sharpen no Strike, your free preparation is off and you cannot set a table). Either way nobody inside can guard, ward, dodge or react, and the guest cannot leave. You act once (the rest of the turn you cast it in), then the guest if it rejected; stations cannot be laid or redeemed inside; then the room strikes and everything is restored. One Welcome per 3 rounds.", expiry: "One full round inside the room, then it collapses.", dependencies: ["a foe in 3"],
      mechanism: "Set the table: a small sealed room where the guest cannot answer.", newEffect: "welcome { room: { w: 3, h: 3, props: [table, chair, chair] }, rounds: 1, choice: [accept, reject], accept: { truce: true, healFrac: 0.15, phi: 6, studies: 2, fedOncePerGuest: true, valence: { guestToHost: 3, guestToAllies: 2, hostToGuest: 1, allyToGuest: 1 }, surrender: 3 }, reject: { fightBack: true, hostDebuff: hospitalityRejected(2) }, directHitAll: true, cooldown: 3 }.",
      reveal: "Welcome takes you and your guest out of the battle for one round: the guest picks a peaceful meal (both fed, no harm) or a fight with no guard or dodge, and you pay if it refuses.", price: "4 ΦF, 25 AP and your turn, once per 3 rounds; a refused meal costs you Hospitality rejected for two rounds, and an accepted one feeds your guest as much as you and warms it towards you.", counter: "Stay out of reach; bank Antifragility and refuse the seat; reject hospitality and fight; accept and take the meal.", teaches: "Hospitality is offered, not forced: the guest chooses." }),
    guestRight: SK("Guest Right", "refined", ["hospitality"], 6, { pairOnly: true, pairs: [["mise_en_place", "hospitality"], ["hospitality", "mise_en_place"]], delivery: "field", range: 3, area: { shape: "single" }, potency: 0, channel: null,
      targetRule: "An ally within 3, or a foe that is currently your guest in a room (a rule the build adds beside the ally rule at targeting.js:259-263, which refuses any foe); never yourself.", prerequisites: ["an ally within 3 (or your guest)", "that unit has not had Guest Right this battle"],
      potencyDefinition: "The target resists 4 damage once a round (not damage from you) and heals 2 at each of its turn ends, for 2 outside rounds (it does not depend on the room). Once a battle per unit (Chef's Table gives each unit one more).", expiry: "2 rounds.", dependencies: ["an ally or a guest in 3"],
      mechanism: "Feed and shield the guest: hospitality protects, not just pacifies.", newEffect: "guestRight { shield: 4, heal: 2, rounds: 2, perTarget: 1 }.",
      reveal: "Guest Right is a single meal: it cannot be refilled on the same unit.", price: "6 ΦF and 35 AP for at most 12 LF of help to one unit, once.", counter: "Spread the damage over rounds (4 once a round); kill the receiver; a gift to a foe is a gift.", teaches: "Guests eat first, and only once." }),
    chefsTable: SK("Chef's Table", "ultimate", ["mise_en_place", "hospitality"], 16, { merge: true, pairOnly: true, pairs: [["mise_en_place", "hospitality"], ["hospitality", "mise_en_place"]], timing: "announced", announce: "Table's ready. Everybody sits.", delivery: "field", range: 0, area: { shape: "radius", radius: 3 }, potency: 0, channel: null,
      targetRule: "Yourself: every unit within 3.", prerequisites: ["Mise en Place AND Hospitality equipped", "a full ultimate charge"],
      potencyDefinition: "Everyone sits: a sealed dining room (5x5, 7x7 if more than eight sit) opens for ONE full round and the outside battle holds its breath. It seats you, every ally within 3 and every eligible foe within 3 (never a boss, wild creature, bystander, civilian, mediator (safe conduct), persuaded unit, unit already in a truce or in a room, unit that has not arrived, has escaped or is defeated, or unit with banked Antifragility; at most ten seats, nearest first). Each guest chooses ACCEPT THE MEAL or REJECT HOSPITALITY. An accepting guest and your side (you, your summons, your allies seated) cannot harm each other; you and each accepting guest heal 15% of maximum LF, recover 6 ΦF and learn two things about each other (each guest once per battle; your allies and any other seated unit are present but not fed, though accepting guests gain valence +3 toward you and +2 toward your allies, and you and your allies gain +1 toward them). A rejecting guest is open to your side and may attack it back; you are penalised once per table however many reject (Hospitality rejected, two rounds). Nobody inside can guard, ward, dodge or react or leave. You act first, then your allies, then rejecting guests, each once. Your stations are made 100% fresh (and lose any opening grace) and wait outside; none is laid or redeemed inside. Every ally seated gains Guest Right. Gated by the ultimate charge (+20 per concept cast, +12 more for alternating), 16 ΦF and 50 AP. The Welcome limit does not apply, but a Table starts it.", expiry: "One full round inside the room, then it collapses.",
      dependencies: ["both concepts", "the Welcome room and Guest Right rules", "stations to be worth much"],
      mechanism: "Merge: the prepared table is set for everyone, and nobody inside can guard or dodge.", newEffect: "chefsTable { room: { w: 5, h: 5, big: 7 }, rounds: 1, choice: [accept, reject], pairwiseTruce: true, fed: [host, acceptingGuests], valence: { guestToHost: 3, guestToAllies: 2, hostToGuest: 1, allyToGuest: 1 }, surrender: 3, hostDebuffOncePerTable: true, directHitAll: true, refreshStations: true, clearGrace: true, guestRight: { resist: 4, heal: 2, rounds: 2 } }.",
      reveal: "Chef's Table is announced; for one round everyone near him sits in a sealed room where nothing can be guarded or dodged, and each guest picks peace or a fight.", price: "16 of his 30 ΦF, 50 AP, a full charge and the announced window; a rejecter fights his whole side with no dodge and he is penalised.", counter: "Stay outside 3; reject hospitality; bank Antifragility and refuse the seat; hit him from outside.", teaches: "A table is an offer: peace if it is accepted, a fight if it is not." }),
