    standIn: SK("Stand In", "basic", ["substitution"], 4, { delivery: "signal", area: { shape: "single" }, targetRule: "One consenting surrogate within 6.", potencyDefinition: "Link keeper to surrogate; the next eligible consequence targeting you resolves on them at full potency.", expiry: "Until caught, battle end, or severed.", dependencies: ["a consenting surrogate", "open signal"], mechanism: "Ask and be answered: bind a distant surrogate to take your next hit.", newEffect: "wardLink { range: 6, catches: 1, consent: true }.", reveal: "The link is public: everyone sees who stands for whom.", price: "Consent required, link public, one link only.", counter: "Sever the signal; feint the catch; fell the surrogate first.", teaches: "Borrowed safety is still safety." }),
